INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима дар бораи муҳимии масофаи шитобҳои қаторӣ дар ҷамъоварии пахта</h2>\n<p>Ҷамъоварии пахта ба сабаби ҳассосии решаҳо ва ниёзи шафоф ба намӣ, яке аз мураккабтарин соҳаҳои кишоварӣ барои системаҳои обёрӣ ҳисоб карда мешавад. Дар обёрӣ қатқатронакии <a href="https://navar-abyari.ir/how-to-choose-suitable-drip-irrigation-tape/">интихоби дурусти шитобҳои қаторӣ</a>муҳандисии масофаи байни қаторҳо (Spacing) нақши муайянкунанда дар якхелагии намии хок ва кам кардани фишорҳои рӯякро дорад. Масофаи шитобҳои қаторӣ танҳо як параметри геометрӣ нест, балки тағйирёбандаи муҳимест, ки бевосита ба чуқуриии дохилшавии решаҳо, суръати бухоршавӣ ва дар натиҷа, ҳосилнокии ниҳоии маҳсул таъсир мерасонад.</p>\n<p>Бисёр деҳқонон бе назардошти чуқуриии решаҳои пахта ва намуди хок, масофаи шитобҳоро бо чашм ангушт мекунанд, ки ин метавонад ба аз даст рафтани об ва паст шудани сифати наҳф ва пул овард. Дар ин мақола, мо тафсилоти техникӣ дар бораи меъёрҳои тавсияшуда барои қаторкунии шитобҳои қаторӣ дар ҷамъоварии пахтаро бо тафсилот баррасӣ мекунем.</p>\n\n\n\n<h2>Меъёрҳои техникӣ барои масофаи шитобҳои қаторӣ дар асоси чуқуриии решаҳо</h2>\n<h3>Таҳлили чуқуриии дохилшавии решаҳои пахта</h3>\n<p>Системаи решаҳои пахта амудӣ ва чуқур аст. Бар асоси таҳқиқоти кишоварӣ, чуқурии муфиди решаҳои пахта вобаста ба марҳилаи рушд ва намуди хок, метавонад аз 60 сантиметр то 1.5 метр тағйир ёбад. Бинобар ин, масофаи шитобҳои қаторӣ бояд ба таври ангушт карда шавад, ки минтақаи намнок (Wetted Zone) дар сатҳи решаҳо тақрризи кофӣ дошта бошад.</p>\n<p>Меъёрҳои тиллоии масофаи шитобҳои қаторӣ дар пахта одатан <strong>60 то 80 сантиметр</strong> аст. Ин масофа имкон медиҳад, ки дар чуқурии 40 то 50 сантиметрии хок, намӣ байни ду шитоб ба сатҳи назаррас расад. Агар масофа аз 60 сантиметр камтар бошад, эҳтимоли обгирии ҳамаҷиҳта (Waterlogging) дар хокҳои гилӣ зиёд мешавад ва агар аз 80 сантиметр бештар бошад, қисмҳое аз хок байни шитобҳо хушк мемонанд ва решаҳои сатҳӣ дар ҳолати фишор мебошанд.</p>\n\n<h3>Таъсири намуди хок ба тартиби қаторҳо</h3>\n<ul>\n  <li><strong>Хокҳои гилӣ (Clay):</strong> Озодишиноии паст доранд. Беҳтар аст, ки масофаи қаторҳо камтар (50 то 60 сантиметр) бошад, то намӣ ба сӯи чуқурӣ ва фазо гузарад, аммо вақти обёрӣ бояд кӯтоҳтар ва бештар бошад.</li>\n  <li><strong>Хокҳои рива (Sandy):</strong> Озодишиноии баланд доранд. Масофаи қаторҳо метавонад то 80 ё ҳатто 1 метр зиёд шавад, зеро намӣ ба зудӣ ба чуқурӣ меравад. Аммо суръати хориҷи дарёзбоиҳо бояд баландтар танзим карда шавад.</li>\n  <li><strong>Хокҳои лумӣ (Loam):</strong> Беҳтарин имконият барои идоракунии намӣ мебошанд. Масофаи стандартӣ 70 то 75 сантиметр барои ин намуди хокҳо идеял аст.</li>\n</ul>\n<p>Барои беҳтар фаҳмонидани таъсири тағйирёбиҳои хок ба идоракунии боғзорҳо, мустаҳкам кардани нуқтаҳои муҳим ҳангоми истифодаи лентарои қатқатӣ тавсия мешавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-پنبه-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت پنبه: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>фосилаи лентаҳои қатқатӣ, ҷойгиркунӣ, сабззот, панаҳ (пахта)</figcaption></figure>\n\n<h2>Намӯнаҳои ҷойгиркунии лентаҳои қатқатӣ: яктарона назар ба дутарона</h2>\n<h3>Фосилаҳо дар тартиби яктарона</h3>\n<p>Дар системаи яктарона, як лентаи қатқатӣ дар миён ё дар канори сатҳҳои пахта ҷой мегирад. Агар лента дар миёни сатҳ бошад, фосила аз лента то маркази сатҳ (масалан, 40 сантиметр) бояд дақиқ ҳисоб карда шавад. Дар ин ҳолат, фосила байни сатҳҳои ҳамсоя бояд ҳадди ақал 1.2 то 1.4 метр бошад, то ки ҳарис кардан ва пудкунии механикивӣ бошад, бе он ки ба лентаҳо зарари расонад.</p>\n\n<h3>Фосилаҳо дар тартиби дутарона</h3>\n<p>Барои парҳезҳои zichтар бо самаранокӣ баланд аз замин, аз лентаҳои дутарона истифода мебаранд. Дар ин система, ду лентаи қатқатӣ дар ҳар сатҳ бо фосилаи 30 то 40 сантиметр аз ҳам иҷро мешаванд ва дар ду тарафи номида ҷой мегиранд. Фосилаи лентаҳои сатҳҳои ҳамсоя бояд 1.5 то 2 метр бошад. Ин тартиб тақсимоти баробартари обро дар атрофи рӯйи реша эҷод мекунад ва фишори ҳароратро кам мекунад.</p>\n<table>\n  <tr>\n    <th>Параметр</th>\n    <th>Фосилаи тавсияшуда барои яктарона</th>\n    <th>Фосилаи тавсияшуда барои дутарона</th>\n  </tr>\n  <tr>\n    <td>Фосила аз сатҳ то сатҳ</td>\n    <td>120 то 140 сантиметр</td>\n    <td>150 то 180 сантиметр</td>\n  </tr>\n  <tr>\n    <td>Фосила аз лента то асоси нест</td>\n    <td>20 то 30 сантиметр</td>\n    <td>15 то 20 сантиметр (барои ҳар ду лента)</td>\n  </tr>\n  <tr>\n    <td>Эъмоқии ҷойгиркунии лента</td>\n    <td>5 то 10 сантиметр</td>\n    <td>5 то 10 сантиметр</td>\n  </tr>\n</table>\n\n<h2>Нуктаҳои амалӣ оид ба гузоштан ва танзими масофаи ленти ороӣ</h2>\n<p>Диққат ба масофаи ленти ороӣ на танҳо бо ниҳолзорӣ оғоз намешавад, балки дар марҳилаи гузоштан ва нигоҳдории он низ аҳамияти ду баробар дорад. Аввал бояд нақши ҷойгиршавии боғ ё заминро дар замин кашида бароред, то офобии хати лентҳо пешгирӣ шавад. Офобии ҳатто 10 сантиметрӣ метавонад ба хушкшавии яктарафаи решаҳо оварда расонад.</p>\n<ul>\n  <li><strong>Истифодаи дилҳои нигоҳдорандаи масофа:</strong> Ҳангоми гузоштани лулаҳо, аз дилҳои махсуси ленти ороӣ истифода кунед, то масофаи дақиқи лент то хок нигоҳ дошта шавад.</li>\n  <li><strong>Ҳамвоқуфӣ бо ниҳолгузор (Planter):</strong> Агар барои ниҳолзари аспиракҳо аз ниҳолгузорҳои механизатсияшуда истифода баред, масофаи лент бояд дақиқан бо масофаи сӯрохиҳои ниҳолгузор мувофиқат кунад.</li>\n  <li><strong>Санҷиши фишори система:</strong> Тағйирот дар фишори системаи ороӣ ба дарозии тармоида (Wetting Length)и ленти ороӣ таъсир мерасонад. Масофаи лентро ҳамеша дар асоси фишори воқеии кории система тарҳрезӣ кунед.</li>\n</ul>\n<p>Барои интихоби масофаи мувофиқи ленти ороӣ дар асоси миқдори оби лозима, омӯзиши арзиши ленти ороӣ барои як гектар чӣ қадар аст? метавонад ба шумо дар интихоби буҷети дуруст кумак кунад. Инчунин, диққат ба танзими системаи ороии замин дар як гектар омили дигарест, ки ба масофаҳои тавсияшуда дар ин мақола таъсир мерасонад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-پنبه-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت پنبه: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>drip tape spacing row layout crop аспирак</figcaption></figure>\n\n\n\n<h2>Таъсири масофаи лент ба нармимодули ва сифати аспирак</h2>\n<p>Таҳқиқот нишон додаанд, ки беҳтар кардани масофаи ленти ороӣ метавонад то 15 фоиз нармимодули аспиракро (Fiber yield) афзоиш бахшонад. Вақте ки масофаи лентҳо аз меъёри стандартӣ бештар бошад, оилои аспирак барои дастрасӣ ба намӣ маҷбур мешавад, ки энергияи бештарро барои афзоиши решаҳои тарафӣ сарф кунад, ки ин барои пар ва пулсаи маҳсулот манфиатнок нест.</p>\n<p>Илова бар аспирак, принсипҳои умумии ҷойгиркунии ленти ороӣ барои дигар наботот бо решаҳои амиқ низ монанд аст. Масалан, дар ниҳолзорҳои боғӣ ё дигар набототи саноатӣ, принсипҳои монанде барои ҳисобкунии рафъоди (дэбӣ) ва масофа вуҷуд доранд. Шумо метавонед бо омӯзиши миқдори тохи сафед дар гектар, муқоисае байни решаҳои амиқи тохи ва аспирак дар самти ҷазби об дошта бошед. Ҳарду намуди наботот ба идоракунии дақиқи намои амиқи хок ниёз доранд.</p>\n\n<h2>Саволҳои бисёр такроршаванда (FAQ)</h2>\n<h3>1. Оё масофаи ленти ороӣ барои ҳамаи марҳилаҳои афзоиши аспирак собит аст?</h3>\n<p>Бале, масофаи физикии лент тағйир намеёбад, аммо бномаи ороӣ (дэбӣ ва вақт) бояд тағйир кунад. Дар марҳилаҳои ибтидоии афзоиш, деби камтар ва вақти кӯтоҳтар тавсия дода мешавад, то ки решаҳои ҷавон дар зеромад қарор нагиранд.</p>\n<h3>2. Агар хоби ман хеле сангноки бошад, масофаи лентҳоро бештар кунам?</h3>\n<p>Не, албатда. Дастуҳои ришагида об авҷи тез мекунад. Агар масофаро зиёд кунед, метавонад баъзе қисмҳои решаҳои сатҳӣ хушк шаванд. Беҳтар аст, ки масофаро 60 то 70 сантиметр нигоҳ доред ва аз нӯриҳо бо андозаи хуруши баланд (масалан, 4 литр дар як метр дар як соат) истифода баред.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-پنبه-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت پنبه: استانداردهای توصیه‌شده - تصویر 3"/><figcaption>drip tape spacing row layout crop пунб</figcaption></figure>\n<h3>3. Нӯри пилотӣ бояд дақиқан дар чуқории чанд сантиметр ҷойгир шавад?</h3>\n<p>Чуқурияти стандарти 5 то 10 сантиметр аст. Чуқурияти бештар боиси он мешавад, ки шидат ба решаҳои асосӣ нарасад ва чуқурияти камтар боиси буғобии тез ва зарардидани нӯр тавассути ғарбонҳои сатҳӣ мешавад.</p>\n\n\n\n<h2>Хулоса</h2>\n<p>Муайян кардани масофаи нӯри пилотӣ дар кабудкунии пунб як раванди муҳандисии дақиқ аст, ки комбинатсияи донистани хок, марҳилаи рушди раҳмон ва фишори системаи обёрорӣро дар бар мегирад. Риояти масофаҳои стандартии 60 то 80 сантиметрӣ ва тартиботи мунтазам калиди дастрасии ба пунбе балидарад ва камтарин истифодаи об аст. ҳамеша аз нӯриҳо бо сифати баланд ва дорои нави барои рӯшноӣ истифода баред, то умри нӯр ба зиёда аз як фаввонаи зиёдтар шавад. Дар ҳолати лозим будани маслиҳати бештар дар бораи ашёи корӣ, муроҷиат ба <a href="https://navar-abyari.ir/green-cumin-seed-amount-per-hectare-planting-care/">рахнаматияи кунуни ҳиндул</a> ё дигар мақолаҳои ихтисосӣ дар сайт ба фаҳмиши беҳтари асосҳои кардани кор ва тарҳрезӣ менамояд.</p>\n<p><strong>Маводи алоқаманд:</strong> <a href="https://navar-abyari.ir/%D8%AA%D9%86%D8%A7%DA%98-%D8%B3%DB%8C%D8%A8-%D8%B2%D9%85%DB%8C%D9%86%DB%8C-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D8AAD986D8A7DA98 D8B3DB8CD8A8 D8B2D985DB8CD986DB8C D8AFD8B1 D987DAA9D8AAD8A7D8B1</a>, <a href="https://navar-abyari.ir/%D9%86%DA%A9%D8%A7%D8%AA-%D9%85%D9%87%D9%85-%D8%AF%D8%B1-%D9%87%D9%86%DA%AF%D8%A7%D9%85-%D8%A7%D8%B3%D8%AA%D9%81%D8%A7%D8%AF%D9%87-%D8%A7%D8%B2-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D8%A2%D8%A8/">D986DAA9D8A7D8AA D985D987D985 D8AFD8B1 D987D986DAAFD8A7D985 D8A7D8B3D8AAD981D8A7D8AFD987 D8A7D8B2 D986D988D8A7D8B1 D8AADB8CD9BE D8A2D8A8</a></p>','Дурӯҳии пӯши тиб дар кӯтокии пахта: Стандартҳои тавсияшуда','Таҳқиқи ихтисосӣ масоҳати шӯрҳои ласо дар ҳосилнокии пахта бо таваҷҷуҳ ба стандартҳои обёрӣ бо насобӣ, тарҳрезии хатҳо ва беҳбудии истифодаи об барои ҳосили баланд.','publish','closed','closed','duruhy-pushi-tib-kutoh-pakhta-standart',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
